"use client"

import * as React from "react"

import { resolveCsvDialect, type CsvDialect, type CsvTable } from "@/lib/csv"
import { cn } from "@/lib/utils"

import { defaultCsvDownloadName, downloadCsvTable } from "./csv-viewer-download"
import { CsvGrid, type CsvGridHandle } from "./csv-viewer-grid"
import {
  getCsvErrorMessage,
  useCsvResourceState,
  type CsvCellAddress,
} from "./csv-viewer-state"
import { CsvViewerToolbar, useCsvViewerZoom } from "./csv-viewer-toolbar"

const BASE_FONT_SIZE = 13

export interface CsvScrollOptions {
  behavior?: ScrollBehavior
}

export interface CsvViewerHandle {
  scrollToCell: (
    cellAddress: CsvCellAddress,
    options?: CsvScrollOptions
  ) => void
  getViewportElement: () => HTMLDivElement | null
}

export interface CsvViewerProps {
  src?: string
  value?: string
  source?: Blob
  data?: CsvTable
  dialect?: CsvDialect
  className?: string
  toolbar?: boolean
  downloadName?: string
  height?: number
  fillHeight?: boolean
  activeCell?: CsvCellAddress | null
  isolateStyles?: boolean
}

export const CsvViewer = React.forwardRef<CsvViewerHandle, CsvViewerProps>(
  function CsvViewer(
    {
      src,
      value,
      data,
      source,
      dialect: dialectProp,
      className,
      toolbar = true,
      downloadName,
      height = 480,
      fillHeight = false,
      activeCell,
      isolateStyles = false,
    },
    ref
  ) {
    const dialect = React.useMemo(
      () =>
        resolveCsvDialect({
          dialect: dialectProp,
          descriptor: { src, fileName: downloadName },
        }),
      [dialectProp, downloadName, src]
    )
    const resourceState = useCsvResourceState({
      src,
      value,
      source,
      data,
      dialect,
    })
    const gridRef = React.useRef<CsvGridHandle>(null)
    const { zoom, setZoom } = useCsvViewerZoom()
    const columns = resourceState.columns
    const sourceRows = resourceState.sourceRows
    const resolvedDownloadName = downloadName ?? defaultCsvDownloadName(dialect)

    React.useImperativeHandle(
      ref,
      () => ({
        scrollToCell: (cellAddress, options) => {
          gridRef.current?.scrollToCell(cellAddress, options)
        },
        getViewportElement: () => gridRef.current?.getViewportElement() ?? null,
      }),
      []
    )

    const handleDownload = React.useCallback(() => {
      void downloadCsvTable({
        src,
        columns,
        sourceRows,
        dialect,
        downloadName: resolvedDownloadName,
      })
    }, [columns, dialect, resolvedDownloadName, sourceRows, src])

    const statusNode = React.useMemo(() => {
      if (resourceState.status === "error") {
        return (
          <div
            role="status"
            aria-live="polite"
            className="flex h-24 items-center justify-center px-3 text-center text-xs text-muted-foreground"
          >
            {getCsvErrorMessage(resourceState.error)}
          </div>
        )
      }
      if (sourceRows.length === 0 && resourceState.status !== "loading") {
        return (
          <div className="flex h-24 items-center justify-center text-xs text-muted-foreground">
            No rows
          </div>
        )
      }
      return null
    }, [resourceState, sourceRows.length])

    return (
      <div
        data-slot="csv-viewer"
        className={cn(
          "flex flex-col overflow-hidden rounded-xl border bg-card",
          fillHeight && "min-h-0 flex-1",
          className
        )}
        style={{ fontSize: BASE_FONT_SIZE * zoom }}
      >
        {toolbar ? (
          <CsvViewerToolbar
            rowCount={sourceRows.length}
            columnCount={columns.length}
            isLoading={resourceState.status === "loading"}
            zoom={zoom}
            onZoomChange={setZoom}
            onDownload={handleDownload}
          />
        ) : null}
        <CsvGrid
          ref={gridRef}
          columns={columns}
          sourceRows={sourceRows}
          activeCell={activeCell ?? null}
          height={height}
          fillHeight={fillHeight}
          isolateStyles={isolateStyles}
          scale={zoom}
          statusNode={statusNode}
        />
      </div>
    )
  }
)

export { type CsvCellAddress, type CsvDialect, type CsvTable }

import { isTabDelimited, type CsvDialect } from "@/lib/csv"

export function escapeDelimitedField(value: string, delimiter: string): string {
  const text = value ?? ""
  return text.includes(delimiter) || /["\r\n]/.test(text)
    ? `"${text.replace(/"/g, '""')}"`
    : text
}

export function serializeCsvTable({
  columns,
  sourceRows,
  dialect,
}: {
  columns: string[]
  sourceRows: string[][]
  dialect: CsvDialect
}): string {
  const lines = [
    columns
      .map((value) => escapeDelimitedField(value, dialect.delimiter))
      .join(dialect.delimiter),
  ]
  for (const sourceRow of sourceRows) {
    lines.push(
      sourceRow
        .map((value) => escapeDelimitedField(value, dialect.delimiter))
        .join(dialect.delimiter)
    )
  }
  return lines.join("\r\n")
}

export function defaultCsvDownloadName(dialect: CsvDialect): string {
  return isTabDelimited(dialect) ? "data.tsv" : "data.csv"
}

export async function downloadCsvTable({
  src,
  columns,
  sourceRows,
  dialect,
  downloadName,
}: {
  src?: string
  columns: string[]
  sourceRows: string[][]
  dialect: CsvDialect
  downloadName: string
}): Promise<void> {
  const blob = src
    ? await fetch(src).then((response) => {
        if (!response.ok) {
          throw new Error(`Failed to load file: ${response.status}`)
        }
        return response.blob()
      })
    : new Blob([serializeCsvTable({ columns, sourceRows, dialect })], {
        type: isTabDelimited(dialect)
          ? "text/tab-separated-values;charset=utf-8"
          : "text/csv;charset=utf-8",
      })
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement("a")
  anchor.href = url
  anchor.download = downloadName
  anchor.rel = "noreferrer"
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
  URL.revokeObjectURL(url)
}

"use client"

import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"
import { ChevronDown, ChevronUp } from "lucide-react"

import { cn } from "@/lib/utils"

import { CSV_SCROLLBAR_CSS, HeaderAwareScrollbar } from "./csv-viewer-scrollbar"
import type { CsvCellAddress } from "./csv-viewer-state"
import { CsvStyleScope } from "./csv-viewer-style-scope"

type Row = string[]

interface ColumnItem {
  index: number
  size: number
}

export interface CsvGridHandle {
  scrollToCell: (
    cellAddress: CsvCellAddress,
    options?: { behavior?: ScrollBehavior }
  ) => void
  getViewportElement: () => HTMLDivElement | null
}

export interface CsvGridProps {
  columns: string[]
  sourceRows: string[][]
  activeCell: CsvCellAddress | null
  height: number
  fillHeight: boolean
  isolateStyles: boolean
  scale: number
  statusNode: React.ReactNode
}

const CSV_TABLE_LABEL = "CSV data"
const COLUMN_WIDTH = 180
const COLUMN_OVERSCAN = 30
const ROW_HEIGHT = 33
const ROW_NUMBER_WIDTH = 56
const ROW_OVERSCAN = 30
const SMALL_TABLE_ROW_LIMIT = 200
const SMALL_TABLE_COLUMN_LIMIT = 20

export const CsvGrid = React.forwardRef<CsvGridHandle, CsvGridProps>(
  function CsvGrid(
    {
      columns,
      sourceRows,
      activeCell,
      height,
      fillHeight,
      isolateStyles,
      scale,
      statusNode,
    },
    ref
  ) {
    const [sort, setSort] = React.useState<{
      columnIndex: number
      descending: boolean
    } | null>(null)

    const toggleSort = React.useCallback((columnIndex: number) => {
      setSort((current) =>
        !current || current.columnIndex !== columnIndex
          ? { columnIndex, descending: false }
          : current.descending
            ? null
            : { columnIndex, descending: true }
      )
    }, [])

    const rowOrder = React.useMemo<number[] | null>(() => {
      if (!sort) return null
      const order = sourceRows.map((_, rowIndex) => rowIndex)
      const { columnIndex } = sort
      order.sort((a, b) =>
        compareCells(
          sourceRows[a][columnIndex] ?? "",
          sourceRows[b][columnIndex] ?? ""
        )
      )
      if (sort.descending) order.reverse()
      return order
    }, [sourceRows, sort])

    const displayIndexByRowIndex = React.useMemo<Map<
      number,
      number
    > | null>(() => {
      if (!rowOrder) return null
      const map = new Map<number, number>()
      rowOrder.forEach((rowIndex, displayRowIndex) => {
        map.set(rowIndex, displayRowIndex)
      })
      return map
    }, [rowOrder])

    const rowAt = React.useCallback(
      (displayRowIndex: number): Row =>
        sourceRows[rowOrder ? rowOrder[displayRowIndex] : displayRowIndex],
      [sourceRows, rowOrder]
    )

    const rowIndexAt = React.useCallback(
      (displayRowIndex: number): number =>
        rowOrder ? rowOrder[displayRowIndex] : displayRowIndex,
      [rowOrder]
    )

    const viewportRef = React.useRef<HTMLDivElement>(null)
    const columnCount = columns.length
    const columnOffset = 1
    const shouldVirtualizeRows = sourceRows.length > SMALL_TABLE_ROW_LIMIT
    const shouldVirtualizeColumns = columnCount > SMALL_TABLE_COLUMN_LIMIT
    const effectiveRowHeight = Math.max(1, Math.round(ROW_HEIGHT * scale))
    const effectiveColumnWidth = Math.max(1, Math.round(COLUMN_WIDTH * scale))
    const effectiveRowNumberWidth = Math.round(ROW_NUMBER_WIDTH * scale)

    const rowVirtualizer = useVirtualizer({
      count: sourceRows.length,
      getScrollElement: () => viewportRef.current,
      estimateSize: () => effectiveRowHeight,
      overscan: ROW_OVERSCAN,
    })

    const columnVirtualizer = useVirtualizer({
      horizontal: true,
      count: columnCount,
      getScrollElement: () => viewportRef.current,
      estimateSize: () => effectiveColumnWidth,
      overscan: COLUMN_OVERSCAN,
    })

    const { columnItems, leftPad, rightPad } = React.useMemo<{
      columnItems: ColumnItem[]
      leftPad: number
      rightPad: number
    }>(() => {
      if (!shouldVirtualizeColumns) {
        return {
          columnItems: columns.map((_, index) => ({
            index,
            size: effectiveColumnWidth,
          })),
          leftPad: 0,
          rightPad: 0,
        }
      }
      const items = columnVirtualizer.getVirtualItems()
      const total = columnVirtualizer.getTotalSize()
      if (items.length === 0 && columnCount > 0) {
        const count = Math.min(columnCount, COLUMN_OVERSCAN)
        return {
          columnItems: Array.from({ length: count }, (_, index) => ({
            index,
            size: effectiveColumnWidth,
          })),
          leftPad: 0,
          rightPad: Math.max(0, total - count * effectiveColumnWidth),
        }
      }
      return {
        columnItems: items.map((item) => ({
          index: item.index,
          size: item.size,
        })),
        leftPad: items.length ? items[0].start : 0,
        rightPad: items.length ? total - items[items.length - 1].end : 0,
      }
      // getVirtualItems is recomputed on scroll/resize; depend on its value.
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [
      shouldVirtualizeColumns,
      columns,
      effectiveColumnWidth,
      columnCount,
      columnVirtualizer.getVirtualItems(),
      columnVirtualizer.getTotalSize(),
    ])

    React.useEffect(() => {
      rowVirtualizer.measure()
      columnVirtualizer.measure()
    }, [
      effectiveRowHeight,
      effectiveColumnWidth,
      rowVirtualizer,
      columnVirtualizer,
    ])

    React.useImperativeHandle(
      ref,
      () => ({
        scrollToCell: (cellAddress, options) => {
          const behavior = options?.behavior ?? "smooth"
          const displayRowIndex =
            displayIndexByRowIndex?.get(cellAddress.rowIndex) ??
            cellAddress.rowIndex
          rowVirtualizer.scrollToIndex(displayRowIndex, {
            align: "center",
            behavior,
          })
          columnVirtualizer.scrollToIndex(cellAddress.columnIndex, {
            align: "center",
            behavior,
          })
        },
        getViewportElement: () => viewportRef.current,
      }),
      [columnVirtualizer, displayIndexByRowIndex, rowVirtualizer]
    )

    const gridTemplate = React.useMemo(
      () =>
        buildGridTemplate({
          rowNumberWidth: effectiveRowNumberWidth,
          leftPad,
          columnItems,
          rightPad,
        }),
      [effectiveRowNumberWidth, leftPad, columnItems, rightPad]
    )
    const totalWidth =
      effectiveRowNumberWidth + columnCount * effectiveColumnWidth
    const virtualRows = rowVirtualizer.getVirtualItems()

    return (
      <div
        data-slot="csv-grid"
        role="table"
        aria-label={CSV_TABLE_LABEL}
        aria-rowcount={sourceRows.length + 1}
        aria-colcount={columnCount + columnOffset}
        className={cn("relative", fillHeight && "min-h-0 flex-1")}
      >
        <CsvStyleScope
          isolate={isolateStyles}
          className={cn("relative", fillHeight && "min-h-0 flex-1")}
          style={fillHeight ? undefined : { height, maxHeight: "100%" }}
        >
          <style>{CSV_SCROLLBAR_CSS}</style>
          <div
            ref={viewportRef}
            data-slot="csv-body"
            className="absolute inset-0 overflow-auto"
          >
            <div
              style={{
                width: totalWidth,
                minWidth: "100%",
                position: "relative",
              }}
            >
              <div
                role="row"
                aria-rowindex={1}
                data-slot="csv-header"
                className="sticky top-0 z-20 grid border-b"
                style={{
                  gridTemplateColumns: gridTemplate,
                  backgroundColor:
                    "color-mix(in oklab, var(--card) 92%, var(--foreground))",
                }}
              >
                <div
                  role="columnheader"
                  aria-colindex={1}
                  aria-label="Row number"
                  className="sticky left-0 z-10 border-r bg-[color-mix(in_oklab,var(--card)_94%,var(--foreground))]"
                  style={{ height: effectiveRowHeight }}
                />
                <Spacer width={leftPad} />
                {columnItems.map((item) => (
                  <HeaderCell
                    key={item.index}
                    name={columns[item.index] || `Column ${item.index + 1}`}
                    columnIndex={columnOffset + item.index + 1}
                    height={effectiveRowHeight}
                    sorted={
                      sort?.columnIndex === item.index
                        ? sort.descending
                          ? "desc"
                          : "asc"
                        : false
                    }
                    onToggle={() => toggleSort(item.index)}
                  />
                ))}
                <Spacer width={rightPad} />
              </div>

              {statusNode ? (
                statusNode
              ) : shouldVirtualizeRows ? (
                <div
                  role="rowgroup"
                  style={{
                    position: "relative",
                    height: rowVirtualizer.getTotalSize(),
                  }}
                >
                  {virtualRows.map((virtualRow) => (
                    <CsvRow
                      key={virtualRow.index}
                      cells={rowAt(virtualRow.index)}
                      displayRowIndex={virtualRow.index}
                      rowIndex={rowIndexAt(virtualRow.index)}
                      gridTemplate={gridTemplate}
                      rowHeight={effectiveRowHeight}
                      columnOffset={columnOffset}
                      columnItems={columnItems}
                      leftPad={leftPad}
                      rightPad={rightPad}
                      start={virtualRow.start}
                      activeColumnIndex={
                        activeCell?.rowIndex === rowIndexAt(virtualRow.index)
                          ? activeCell.columnIndex
                          : null
                      }
                    />
                  ))}
                </div>
              ) : (
                <div role="rowgroup">
                  {sourceRows.map((_, displayRowIndex) => (
                    <CsvRow
                      key={displayRowIndex}
                      cells={rowAt(displayRowIndex)}
                      displayRowIndex={displayRowIndex}
                      rowIndex={rowIndexAt(displayRowIndex)}
                      gridTemplate={gridTemplate}
                      rowHeight={effectiveRowHeight}
                      columnOffset={columnOffset}
                      columnItems={columnItems}
                      leftPad={leftPad}
                      rightPad={rightPad}
                      activeColumnIndex={
                        activeCell?.rowIndex === rowIndexAt(displayRowIndex)
                          ? activeCell.columnIndex
                          : null
                      }
                    />
                  ))}
                </div>
              )}
            </div>
          </div>
          <HeaderAwareScrollbar
            viewportRef={viewportRef}
            headerHeight={effectiveRowHeight}
          />
        </CsvStyleScope>
      </div>
    )
  }
)

function buildGridTemplate({
  rowNumberWidth,
  leftPad,
  columnItems,
  rightPad,
}: {
  rowNumberWidth: number
  leftPad: number
  columnItems: ColumnItem[]
  rightPad: number
}) {
  const columns = columnItems.map((column) => `${column.size}px`).join(" ")
  return [`${rowNumberWidth}px`, `${leftPad}px`, columns, `${rightPad}px`]
    .filter(Boolean)
    .join(" ")
}

function Spacer({ width }: { width: number }) {
  return <div role="presentation" aria-hidden style={{ width }} />
}

function HeaderCell({
  name,
  columnIndex,
  height,
  sorted,
  onToggle,
}: {
  name: string
  columnIndex: number
  height: number
  sorted: "asc" | "desc" | false
  onToggle: () => void
}) {
  return (
    <div
      role="columnheader"
      aria-colindex={columnIndex}
      aria-sort={
        sorted === "asc"
          ? "ascending"
          : sorted === "desc"
            ? "descending"
            : "none"
      }
      data-slot="csv-header-cell"
      className="border-r last:border-r-0"
    >
      <button
        type="button"
        onClick={onToggle}
        className="flex w-full items-center gap-1 px-3 text-left font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:bg-muted focus-visible:outline-none"
        style={{ height }}
        title={`Sort by ${name}`}
      >
        <span className="truncate">{name}</span>
        {sorted ? (
          sorted === "asc" ? (
            <ChevronUp
              className="size-3.5 shrink-0 text-muted-foreground"
              aria-hidden
            />
          ) : (
            <ChevronDown
              className="size-3.5 shrink-0 text-muted-foreground"
              aria-hidden
            />
          )
        ) : null}
      </button>
    </div>
  )
}

function compareCells(a: string, b: string): number {
  const left = Number(a)
  const right = Number(b)
  if (a !== "" && b !== "" && !Number.isNaN(left) && !Number.isNaN(right)) {
    return left - right
  }
  return a < b ? -1 : a > b ? 1 : 0
}

const CsvRow = React.memo(function CsvRow({
  cells,
  displayRowIndex,
  rowIndex,
  gridTemplate,
  rowHeight,
  columnOffset,
  columnItems,
  leftPad,
  rightPad,
  start,
  activeColumnIndex,
}: {
  cells: Row | undefined
  displayRowIndex: number
  rowIndex: number
  gridTemplate: string
  rowHeight: number
  columnOffset: number
  columnItems: ColumnItem[]
  leftPad: number
  rightPad: number
  start?: number
  activeColumnIndex?: number | null
}) {
  const style: React.CSSProperties =
    start === undefined
      ? { gridTemplateColumns: gridTemplate, height: rowHeight }
      : {
          gridTemplateColumns: gridTemplate,
          height: rowHeight,
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          transform: `translateY(${start}px)`,
        }
  return (
    <div
      role="row"
      aria-rowindex={displayRowIndex + 2}
      data-slot="csv-row"
      className="group grid border-b hover:bg-muted/40"
      style={style}
    >
      <div
        role="rowheader"
        aria-colindex={1}
        data-slot="csv-row-number"
        className="sticky left-0 z-[1] flex items-center justify-end border-r bg-card px-2 text-muted-foreground tabular-nums group-hover:bg-[color-mix(in_oklab,var(--card)_97%,var(--foreground))]"
      >
        {rowIndex + 1}
      </div>
      <Spacer width={leftPad} />
      {columnItems.map((item) => {
        const text = cells?.[item.index] ?? ""
        const isActive = activeColumnIndex === item.index
        return (
          <div
            key={item.index}
            role="cell"
            aria-colindex={columnOffset + item.index + 1}
            data-slot="csv-cell"
            className={cn(
              "flex items-center truncate border-r px-3 last:border-r-0",
              isActive &&
                "bg-primary/12 ring-1 ring-primary/50 ring-offset-0 ring-inset"
            )}
            title={text}
          >
            <span className="truncate">{text}</span>
          </div>
        )
      })}
      <Spacer width={rightPad} />
    </div>
  )
})

"use client"

import * as React from "react"

export const CSV_SCROLLBAR_CSS = `
[data-slot="csv-body"]::-webkit-scrollbar { width: 10px; height: 10px; }
[data-slot="csv-body"]::-webkit-scrollbar:vertical { display: none; }
[data-slot="csv-body"]::-webkit-scrollbar-track { background: transparent; }
[data-slot="csv-body"]::-webkit-scrollbar-thumb {
  background-color: color-mix(in oklab, var(--foreground) 22%, transparent);
  border-radius: 9999px;
  border: 3px solid transparent;
  background-clip: content-box;
}
[data-slot="csv-body"]::-webkit-scrollbar-thumb:hover {
  background-color: color-mix(in oklab, var(--foreground) 38%, transparent);
}
`

export function HeaderAwareScrollbar({
  viewportRef,
  headerHeight,
}: {
  viewportRef: React.RefObject<HTMLDivElement | null>
  headerHeight: number
}) {
  const [thumb, setThumb] = React.useState({ height: 0, top: 0, show: false })
  const drag = React.useRef<{ y: number; scroll: number } | null>(null)

  const measure = React.useCallback(() => {
    const viewportElement = viewportRef.current
    if (!viewportElement) return
    const { scrollHeight, clientHeight, scrollTop } = viewportElement
    const track = clientHeight - headerHeight
    if (scrollHeight <= clientHeight + 1 || track <= 0) {
      setThumb((current) =>
        current.show ? { ...current, show: false } : current
      )
      return
    }
    const height = Math.max(28, (clientHeight / scrollHeight) * track)
    const max = scrollHeight - clientHeight
    const top = max > 0 ? (scrollTop / max) * (track - height) : 0
    setThumb({ height, top, show: true })
  }, [viewportRef, headerHeight])

  React.useEffect(() => {
    const viewportElement = viewportRef.current
    if (!viewportElement) return
    measure()
    viewportElement.addEventListener("scroll", measure, { passive: true })
    const observer = new ResizeObserver(measure)
    observer.observe(viewportElement)
    return () => {
      viewportElement.removeEventListener("scroll", measure)
      observer.disconnect()
    }
  }, [viewportRef, measure])

  const onPointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    const viewportElement = viewportRef.current
    if (!viewportElement) return
    event.preventDefault()
    drag.current = { y: event.clientY, scroll: viewportElement.scrollTop }
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  const onPointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    const viewportElement = viewportRef.current
    const currentDrag = drag.current
    if (!viewportElement || !currentDrag) return
    const track = viewportElement.clientHeight - headerHeight
    const height = Math.max(
      28,
      (viewportElement.clientHeight / viewportElement.scrollHeight) * track
    )
    const denominator = track - height
    if (denominator <= 0) return
    const max = viewportElement.scrollHeight - viewportElement.clientHeight
    viewportElement.scrollTop =
      currentDrag.scroll + ((event.clientY - currentDrag.y) / denominator) * max
  }

  const endDrag = (event: React.PointerEvent<HTMLDivElement>) => {
    drag.current = null
    event.currentTarget.releasePointerCapture?.(event.pointerId)
  }

  if (!thumb.show) return null
  return (
    <div
      aria-hidden
      className="pointer-events-none absolute right-0 z-30 w-2.5"
      style={{ top: headerHeight, bottom: 0 }}
    >
      <div
        className="pointer-events-auto absolute right-0.5 w-1.5 rounded-full bg-foreground/25 transition-colors hover:bg-foreground/40"
        style={{ height: thumb.height, top: thumb.top }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
      />
    </div>
  )
}

import type { CsvTable } from "@/lib/csv"

export type CsvResource =
  | { kind: "src"; src: string }
  | { kind: "source"; source: Blob }
  | { kind: "value"; value: string }
  | { kind: "data"; csvTable: CsvTable }
  | { kind: "empty" }

export interface CsvResourceInput {
  src?: string
  value?: string
  source?: Blob
  data?: CsvTable
}

export function resolveCsvResource({
  src,
  source,
  value,
  data,
}: CsvResourceInput): CsvResource {
  if (src) return { kind: "src", src }
  if (source) return { kind: "source", source }
  if (value != null) return { kind: "value", value }
  if (data) return { kind: "data", csvTable: data }
  return { kind: "empty" }
}

import * as React from "react"

import {
  padRowsToColumnCount,
  parseCsv,
  streamCsv,
  type CsvDialect,
  type CsvStreamSource,
} from "@/lib/csv"

import {
  resolveCsvResource,
  type CsvResourceInput,
} from "./csv-viewer-resource"
import { parseCsvInWorker } from "./csv-viewer-worker"

const CSV_STREAM_BATCH_SIZE = 5000

export interface CsvCellAddress {
  rowIndex: number
  columnIndex: number
}

export type CsvViewerError =
  | { kind: "fetch"; status?: number }
  | { kind: "decode" }
  | { kind: "worker" }
  | { kind: "aborted" }
  | { kind: "unknown"; message?: string }

export type CsvResourceState =
  | { status: "idle"; columns: string[]; sourceRows: string[][] }
  | { status: "loading"; columns: string[]; sourceRows: string[][] }
  | { status: "ready"; columns: string[]; sourceRows: string[][] }
  | { status: "empty"; columns: string[]; sourceRows: string[][] }
  | {
      status: "error"
      columns: string[]
      sourceRows: string[][]
      error: CsvViewerError
    }

export function getCsvErrorMessage(error: CsvViewerError): string {
  if (error.kind === "fetch") {
    return error.status
      ? `Failed to load file: ${error.status}`
      : "Couldn't load this file."
  }
  if (error.kind === "decode") return "Couldn't decode this file."
  if (error.kind === "worker") return "Couldn't parse this file."
  if (error.kind === "aborted") return "Loading was cancelled."
  return error.message || "Couldn't load this file."
}

export function unknownToCsvError(error: unknown): CsvViewerError {
  if (error instanceof DOMException && error.name === "AbortError") {
    return { kind: "aborted" }
  }
  if (error instanceof Error) return { kind: "unknown", message: error.message }
  return { kind: "unknown", message: String(error) }
}

export function readyCsvState(
  columns: string[],
  sourceRows: string[][]
): CsvResourceState {
  return sourceRows.length === 0
    ? { status: "empty", columns, sourceRows }
    : { status: "ready", columns, sourceRows }
}

export function useCsvResourceState({
  src,
  value,
  source,
  data,
  dialect,
}: CsvResourceInput & {
  dialect: CsvDialect
}): CsvResourceState {
  const csvResource = React.useMemo(
    () => resolveCsvResource({ src, source, value, data }),
    [data, source, src, value]
  )
  const syncState = React.useMemo<CsvResourceState | null>(() => {
    if (csvResource.kind === "data") {
      return readyCsvState(
        csvResource.csvTable.columns,
        csvResource.csvTable.rows
      )
    }
    if (csvResource.kind === "value") {
      const table = parseCsv(csvResource.value, dialect)
      return readyCsvState(table.columns, table.rows)
    }
    if (csvResource.kind === "empty") {
      return { status: "idle", columns: [], sourceRows: [] }
    }
    return null
  }, [csvResource, dialect])

  const [state, setState] = React.useState<CsvResourceState>({
    status: "idle",
    columns: [],
    sourceRows: [],
  })

  React.useEffect(() => {
    if (csvResource.kind !== "src" && csvResource.kind !== "source") return

    const controller = new AbortController()
    const sourceRows: string[][] = []
    let columns: string[] = []
    let cancelled = false
    setState({ status: "loading", columns: [], sourceRows: [] })

    const onColumns = (next: string[]) => {
      if (cancelled) return
      columns = next
      padRowsToColumnCount(sourceRows, columns.length)
      setState({ status: "loading", columns, sourceRows: sourceRows.slice() })
    }

    const onSourceRows = (sourceRowBatch: string[][]) => {
      if (cancelled) return
      sourceRows.push(...sourceRowBatch)
      setState({ status: "loading", columns, sourceRows: sourceRows.slice() })
    }

    const onDone = () => {
      if (cancelled) return
      setState(readyCsvState(columns, sourceRows.slice()))
    }

    const onError = (error: unknown) => {
      if (cancelled || controller.signal.aborted) return
      setState({
        status: "error",
        columns,
        sourceRows: sourceRows.slice(),
        error: unknownToCsvError(error),
      })
    }

    const runMainThread = (input: CsvStreamSource) => {
      void streamCsv(
        input,
        { onColumns, onRows: onSourceRows, onDone, onError },
        {
          delimiter: dialect.delimiter,
          hasHeader: dialect.hasHeader,
          batchSize: CSV_STREAM_BATCH_SIZE,
          signal: controller.signal,
        }
      )
    }

    const runSrc = async () => {
      if (csvResource.kind !== "src") return
      try {
        const response = await fetch(csvResource.src, {
          signal: controller.signal,
        })
        if (!response.ok) {
          setState({
            status: "error",
            columns,
            sourceRows: sourceRows.slice(),
            error: { kind: "fetch", status: response.status },
          })
          return
        }
        if (response.body) runMainThread(response.body)
        else runMainThread(await response.blob())
      } catch (error) {
        onError(error)
      }
    }

    if (csvResource.kind === "src") {
      void runSrc()
    } else if (typeof Worker !== "undefined") {
      void parseCsvInWorker({
        source: csvResource.source,
        dialect,
        batchSize: CSV_STREAM_BATCH_SIZE,
        onColumns,
        onSourceRows,
        signal: controller.signal,
      }).then(onDone, (error) => {
        if (error instanceof Error && error.message === "worker-unavailable") {
          runMainThread(csvResource.source)
        } else {
          onError(error)
        }
      })
    } else {
      runMainThread(csvResource.source)
    }

    return () => {
      cancelled = true
      controller.abort()
    }
  }, [csvResource, dialect])

  return syncState ?? state
}

"use client"

import * as React from "react"
import { createPortal } from "react-dom"

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

export function stripHasRules(owner: CSSStyleSheet | CSSGroupingRule) {
  const rules = owner.cssRules
  if (!rules) return
  for (let index = rules.length - 1; index >= 0; index--) {
    const rule = rules[index]
    if ((rule as CSSStyleRule).selectorText?.includes(":has(")) {
      try {
        owner.deleteRule(index)
      } catch {
        // Ignore rules that cannot be removed.
      }
    } else if ((rule as CSSGroupingRule).cssRules?.length) {
      stripHasRules(rule as CSSGroupingRule)
    }
  }
}

let sharedSheets: CSSStyleSheet[] | null = null
function getSharedSheets(): CSSStyleSheet[] {
  if (sharedSheets) return sharedSheets
  const sheets: CSSStyleSheet[] = []
  for (const sheet of Array.from(document.styleSheets)) {
    let rules: CSSRuleList
    try {
      rules = sheet.cssRules
    } catch {
      continue
    }
    let text = ""
    for (const rule of Array.from(rules)) text += rule.cssText + "\n"
    try {
      const clone = new CSSStyleSheet()
      clone.replaceSync(text)
      stripHasRules(clone)
      sheets.push(clone)
    } catch {
      // Skip stylesheets that cannot be reconstructed.
    }
  }
  sharedSheets = sheets
  return sheets
}

function ShadowScope({
  className,
  style,
  children,
}: {
  className?: string
  style?: React.CSSProperties
  children: React.ReactNode
}) {
  const hostRef = React.useRef<HTMLDivElement>(null)
  const [root, setRoot] = React.useState<ShadowRoot | null>(null)

  useIsomorphicLayoutEffect(() => {
    const host = hostRef.current
    if (!host) return
    const shadowRoot = host.shadowRoot ?? host.attachShadow({ mode: "open" })
    try {
      shadowRoot.adoptedStyleSheets = getSharedSheets()
    } catch {
      for (const node of Array.from(
        document.querySelectorAll('style, link[rel="stylesheet"]')
      )) {
        try {
          shadowRoot.appendChild(node.cloneNode(true))
        } catch {
          // Ignore nodes that cannot be cloned.
        }
      }
    }
    setRoot(shadowRoot)
  }, [])

  return (
    <div ref={hostRef} className={className} style={style}>
      {root ? createPortal(children, root) : null}
    </div>
  )
}

export function CsvStyleScope({
  isolate,
  className,
  style,
  children,
}: {
  isolate: boolean
  className?: string
  style?: React.CSSProperties
  children: React.ReactNode
}) {
  if (isolate) {
    return (
      <ShadowScope className={className} style={style}>
        {children}
      </ShadowScope>
    )
  }
  return (
    <div className={className} style={style}>
      {children}
    </div>
  )
}

import type { CsvDialect } from "@/lib/csv"

export interface CsvWorkerRequest {
  parseRequestId: string
  source: Blob
  dialect: CsvDialect
  batchSize: number
}

export type CsvWorkerResponse =
  | { type: "columns"; parseRequestId: string; columns: string[] }
  | { type: "sourceRows"; parseRequestId: string; sourceRows: string[][] }
  | { type: "done"; parseRequestId: string }
  | { type: "error"; parseRequestId: string; message: string }

export function createCsvWorker(): Worker {
  return new Worker(new URL("./csv-viewer.worker.ts", import.meta.url), {
    type: "module",
  })
}

export function parseCsvInWorker({
  source,
  dialect,
  batchSize,
  onColumns,
  onSourceRows,
  signal,
}: {
  source: Blob
  dialect: CsvDialect
  batchSize: number
  onColumns: (columns: string[]) => void
  onSourceRows: (sourceRows: string[][]) => void
  signal: AbortSignal
}): Promise<void> {
  return new Promise((resolve, reject) => {
    let worker: Worker
    try {
      worker = createCsvWorker()
    } catch {
      reject(new Error("worker-unavailable"))
      return
    }

    const parseRequestId = crypto.randomUUID()
    const cleanup = () => {
      signal.removeEventListener("abort", abort)
      worker.terminate()
    }
    const abort = () => {
      cleanup()
      reject(new DOMException("Aborted", "AbortError"))
    }

    signal.addEventListener("abort", abort, { once: true })
    worker.onerror = () => {
      cleanup()
      reject(new Error("worker-error"))
    }
    worker.onmessage = (event: MessageEvent<CsvWorkerResponse>) => {
      const message = event.data
      if (message.parseRequestId !== parseRequestId) return
      if (message.type === "columns") onColumns(message.columns)
      else if (message.type === "sourceRows") onSourceRows(message.sourceRows)
      else if (message.type === "done") {
        cleanup()
        resolve()
      } else {
        cleanup()
        reject(new Error(message.message || "worker-error"))
      }
    }

    const request: CsvWorkerRequest = {
      parseRequestId,
      source,
      dialect,
      batchSize,
    }
    worker.postMessage(request)
  })
}

import {
  createCsvNormalizer,
  createCsvParser,
  padRowsToColumnCount,
  type CsvDialect,
} from "@/lib/csv"

import type { CsvWorkerRequest, CsvWorkerResponse } from "./csv-viewer-worker"

function post(message: CsvWorkerResponse) {
  self.postMessage(message)
}

async function* readWorkerTextChunks(source: Blob): AsyncGenerator<string> {
  const reader = source.stream().getReader()
  const decoder = new TextDecoder()
  try {
    while (true) {
      const { done, value } = await reader.read()
      if (done) break
      if (value) {
        const text = decoder.decode(value, { stream: true })
        if (text) yield text
      }
    }
    const rest = decoder.decode()
    if (rest) yield rest
  } finally {
    reader.releaseLock()
  }
}

async function parseInWorker({
  parseRequestId,
  source,
  dialect,
  batchSize,
}: CsvWorkerRequest) {
  const parser = createCsvParser({ delimiter: dialect.delimiter })
  const normalizer = createCsvNormalizer({ hasHeader: dialect.hasHeader })
  let sourceRowBatch: string[][] = []

  const handleRecords = (records: string[][]) => {
    for (const record of records) {
      for (const event of normalizer.accept(record)) {
        if (event.type === "columns") {
          padRowsToColumnCount(sourceRowBatch, event.columns.length)
          post({ type: "columns", parseRequestId, columns: event.columns })
        } else {
          sourceRowBatch.push(event.row)
        }
      }
      if (sourceRowBatch.length >= batchSize) {
        post({
          type: "sourceRows",
          parseRequestId,
          sourceRows: sourceRowBatch,
        })
        sourceRowBatch = []
      }
    }
  }

  for await (const chunk of readWorkerTextChunks(source)) {
    handleRecords(parser.push(chunk))
  }
  handleRecords(parser.flush())
  if (sourceRowBatch.length) {
    post({
      type: "sourceRows",
      parseRequestId,
      sourceRows: sourceRowBatch,
    })
  }
  post({ type: "done", parseRequestId })
}

self.onmessage = (event: MessageEvent<CsvWorkerRequest>) => {
  void parseInWorker(event.data).catch((error) => {
    const message = error instanceof Error ? error.message : String(error)
    post({
      type: "error",
      parseRequestId: event.data.parseRequestId,
      message,
    })
  })
}
